        cin >> a >> b >> c;
        g[a].push_back({b, c});
        g[b].push_back({a, c});
    }

    // First BFS to find one endpoint of the diameter
    auto bfs = [&](int start) -> pair<long long, vector<int>> {
        vector<long long> dist(N, -1);
        queue<int> q;
        dist[start] = 0;
        q.push(start);
        int farthest = start;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (dist[u] > dist[farthest]) farthest = u;
            for (auto [v, w] : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + w;
                    q.push(v);
                }
            }
        }
        return {dist[farthest], dist};
    };

    auto [_, dist1] = bfs(0);
    int end1 = max_element(dist1.begin(), dist1.end()) - dist1.begin();
    auto [diam, distFromEnd1] = bfs(end1);
    int end2 = max_element(distFromEnd1.begin(), distFromEnd1.end()) - distFromEnd1.begin();
    auto [_, distFromEnd2] = bfs(end2);

    // Towns that lie on some diameter
    vector<bool> onDiameter(N, false);
    for (int i = 0; i < N; i++) {
        if (distFromEnd1[i] + distFromEnd2[i] == diam) {
