using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    while (cin >> N >> M) {
        if (N == 0 && M == 0) break;

        const long long INF = (1LL << 60);
        vector<vector<long long>> dist(N, vector<long long>(N, INF));

        for (int i = 0; i < N; i++) dist[i][i] = 0;

        for (int i = 0; i < M; i++) {
            int a, b;
            long long c;
            cin >> a >> b >> c;
            --a; --b;
            dist[a][b] = min(dist[a][b], c);
            dist[b][a] = min(dist[b][a], c);
        }

        // Floyd-Warshall
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                if (dist[i][k] == INF) continue;
                for (int j = 0; j < N; j++) {
                    if (dist[k][j] == INF) continue;
                    long long nd = dist[i][k] + dist[k][j];
                    if (nd < dist[i][j]) dist[i][j] = nd;
                }
            }
        }

        long long diameter = -1;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i][j] < INF) diameter = max(diameter, dist[i][j]);
            }
        }

        vector<bool> used(N, false);
        for (int s = 0; s < N; s++) {
            for (int t = s + 1; t < N; t++) {
                if (dist[s][t] != diameter) continue;
                for (int v = 0; v < N; v++) {
                    if (dist[s][v] < INF && dist[v][t] < INF &&
                        dist[s][v] + dist[v][t] == dist[s][t]) {
                        used[v] = true;
                    }
                }
            }
        }

        vector<int> ans;
        for (int i = 0; i < N; i++) {
            if (!used[i]) ans.push_back(i + 1);
        }

        cout << ans.size() << "\n";
        for (int i = 0; i < (int)ans.size(); i++) {
            if (i) cout << ' ';
            cout << ans[i];
        }
        cout << "\n";
    }

    return 0;
}

#include <stdio.h>
