#define MAXN 200005

typedef struct Edge {
    int to, next;
} Edge;

Edge edges[MAXN * 2];
int head[MAXN];
int edge_cnt;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int dist_u[MAXN], dist_v[MAXN];
int queue[MAXN];

void bfs(int start, int dist[], int n) {
    int front = 0, rear = 0;
    for (int i = 1; i <= n; i++) dist[i] = -1;
    dist[start] = 0;
    queue[rear++] = start;
    while (front < rear) {
        int u = queue[front++];
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
        }
    }
}

int main() {
