#define INF 1000000000

int main(void) {
    int N, M;
    while (scanf("%d %d", &N, &M) == 2) {
        if (N == 0 && M == 0) break;

        int *dist = (int *)malloc(sizeof(int) * N * N);
        if (!dist) return 1;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                dist[i * N + j] = (i == j) ? 0 : INF;
            }
        }

        for (int i = 0; i < M; i++) {
            int a, b, c;
            scanf("%d %d %d", &a, &b, &c);
            a--; b--;
            if (c < dist[a * N + b]) {
                dist[a * N + b] = c;
                dist[b * N + a] = c;
            }
        }

        /* Floyd-Warshall */
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                int dik = dist[i * N + k];
                if (dik == INF) continue;
                for (int j = 0; j < N; j++) {
                    int dkj = dist[k * N + j];
                    if (dkj == INF) continue;
                    int nd = dik + dkj;
                    if (nd < dist[i * N + j]) dist[i * N + j] = nd;
                }
            }
        }

        /* Find diameter length */
        int diameter = 0;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (dist[i * N + j] < INF && dist[i * N + j] > diameter) {
                    diameter = dist[i * N + j];
                }
            }
        }

        /* Mark towns that can be on some diameter path */
        int *used = (int *)calloc(N, sizeof(int));
        if (!used) {
            free(dist);
            return 1;
        }

        for (int s = 0; s < N; s++) {
            for (int t = 0; t < N; t++) {
                if (dist[s * N + t] == diameter) {
                    for (int v = 0; v < N; v++) {
                        if (dist[s * N + v] < INF && dist[v * N + t] < INF &&
                            dist[s * N + v] + dist[v * N + t] == diameter) {
                            used[v] = 1;
                        }
                    }
                }
            }
        }

        int first = 1;
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                if (!first) printf(" ");
                printf("%d", i + 1);
                first = 0;
            }
        }
        printf("\n");

        free(dist);
        free(used);
    }
    return 0;
}

import java.io.*;
