public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) adj.add(new ArrayList<>());

        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            adj.get(a).add(b);
            adj.get(b).add(a);
        }

        // BFS from node 0 to find one endpoint of the diameter
        int[] dist0 = bfs(adj, 0, N);
        int u = 0;
        for (int i = 0; i < N; i++) {
            if (dist0[i] > dist0[u]) u = i;
        }

        // BFS from u to find other endpoint v and distances from u
        int[] distU = bfs(adj, u, N);
        int v = 0;
        for (int i = 0; i < N; i++) {
            if (distU[i] > distU[v]) v = i;
        }

        // BFS from v to get distances from v
        int[] distV = bfs(adj, v, N);
        int diameter = distU[v];

        // Find nodes not on any diameter
        List<Integer> quiet = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            if (distU[i] + distV[i] != diameter) {
                quiet.add(i);
            }
        }

        // Output
        StringBuilder sb = new StringBuilder();
        for (int q : quiet) {
            sb.append(q).append("\n");
        }
        System.out.print(sb.toString());
    }

    static int[] bfs(List<List<Integer>> adj, int start, int N) {
        int[] dist = new int[N];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        dist[start] = 0;
        q.add(start);
        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int next : adj.get(cur)) {
                if (dist[next] == -1) {
                    dist[next] = dist[cur] + 1;
                    q.add(next);
                }
            }
        }
        return dist;
    }
}

