public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        long[][] dist = new long[N][N];
        long INF = Long.MAX_VALUE / 2;

        for (long[] row : dist) Arrays.fill(row, INF);
        for (int i = 0; i < N; i++) dist[i][i] = 0;

        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            long w = sc.nextLong();
            dist[u][v] = Math.min(dist[u][v], w);
            dist[v][u] = Math.min(dist[v][u], w);
        }

        // Floyd-Warshall
        for (int k = 0; k < N; k++)
            for (int i = 0; i < N; i++)
                for (int j = 0; j < N; j++)
                    if (dist[i][k] < INF && dist[k][j] < INF)
                        dist[i][j] = Math.min(dist[i][j], dist[i][k] + dist[k][j]);

        // Find diameter
        long diameter = 0;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (dist[i][j] < INF)
                    diameter = Math.max(diameter, dist[i][j]);

        // Find all nodes on shortest paths of diameter pairs
        boolean[] used = new boolean[N];
        for (int u = 0; u < N; u++) {
            for (int v = 0; v < N; v++) {
                if (dist[u][v] == diameter) {
                    // Mark all nodes on shortest paths between u and v
                    for (int k = 0; k < N; k++) {
                        if (dist[u][k] < INF && dist[k][v] < INF &&
                            dist[u][k] + dist[k][v] == diameter) {
                            used[k] = true;
                        }
                    }
                }
            }
        }

        // Output towns not used
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                sb.append(i + 1).append("\n");
            }
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }
            int m = fs.nextInt();
            if (n == 0 && m == 0) break;

            final long INF = (long) 1e18;
            long[][] dist = new long[n][n];

            for (int i = 0; i < n; i++) {
                Arrays.fill(dist[i], INF);
                dist[i][i] = 0;
            }

            for (int i = 0; i < m; i++) {
                int a = fs.nextInt() - 1;
                int b = fs.nextInt() - 1;
                int c = fs.nextInt();
                if (c < dist[a][b]) {
                    dist[a][b] = c;
                    dist[b][a] = c;
                }
            }

            // Floyd-Warshall
            for (int k = 0; k < n; k++) {
                for (int i = 0; i < n; i++) {
                    if (dist[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if (dist[k][j] == INF) continue;
                        long nd = dist[i][k] + dist[k][j];
                        if (nd < dist[i][j]) dist[i][j] = nd;
                    }
                }
            }

            // Diameter of the graph among reachable pairs
            long diameter = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][j] != INF && dist[i][j] > diameter) {
                        diameter = dist[i][j];
                    }
                }
            }

            List<Integer> ans = new ArrayList<>();

            // A town can be used in some relay course iff it lies on at least one diameter shortest path:
            // exists s, t such that dist[s][t] = diameter and dist[s][v] + dist[v][t] = dist[s][t].
            for (int v = 0; v < n; v++) {
                boolean used = false;
                for (int s = 0; s < n && !used; s++) {
                    if (dist[s][v] == INF) continue;
                    for (int t = 0; t < n; t++) {
                        if (dist[v][t] == INF || dist[s][t] != diameter) continue;
                        if (dist[s][v] + dist[v][t] == diameter) {
                            used = true;
                            break;
                        }
                    }
                }
                if (!used) ans.add(v + 1);
            }

            if (ans.isEmpty()) {
                out.append("0\n");
            } else {
                for (int i = 0; i < ans.size(); i++) {
                    if (i > 0) out.append(' ');
                    out.append(ans.get(i));
                }
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

import sys
from heapq import heappush, heappop

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1
    M = int(input_data[idx]); idx += 1

    INF = float('inf')
    adj = [[] for _ in range(N)]

    for _ in range(M):
        u = int(input_data[idx])-1; idx += 1
        v = int(input_data[idx])-1; idx += 1
        w = int(input_data[idx]); idx += 1
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra from each node
    dist = []
    for s in range(N):
        d = [INF] * N
        d[s] = 0
        pq = [(0, s)]
        while pq:
            dd, u = heappop(pq)
            if dd > d[u]:
                continue
            for v, w in adj[u]:
                if d[u] + w < d[v]:
                    d[v] = d[u] + w
                    heappush(pq, (d[v], v))
        dist.append(d)

    # Find diameter
    diameter = 0
    for i in range(N):
        for j in range(N):
            if dist[i][j] != INF:
                diameter = max(diameter, dist[i][j])

    # Find all nodes that are endpoints of diameter pairs
    used = set()
    for i in range(N):
        for j in range(N):
            if dist[i][j] == diameter:
                used.add(i)
                used.add(j)

    # Nodes not used
    result = []
    for i in range(N):
        if i not in used:
            result.append(i+1)

    for r in result:
        print(r)

